const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const walvisBay = ee.Geometry.Point(14.505, -22.957); // Approximate center of Walvis Bay
    const analysisRegion = walvisBay.buffer(10000); // 10 km buffer around Walvis Bay

    const targetYear = 2021;
    const month = 2; // February

    const startTarget = ee.Date.fromYMD(targetYear, month, 1);
    const endTarget = ee.Date.fromYMD(targetYear, month, 1).advance(1, 'month');

    const startBaselineYear = 2010;
    const endBaselineYear = 2020;

    // 2. Data Acquisition & Preprocessing
    // Function to mask clouds for Landsat 5, 7, 8 SR collections
    function maskL8Cloud(image) {
      const qa = image.select('QA_PIXEL');
      // Bits 3 and 5 are cloud shadow and cloud, respectively.
      const cloudShadowBitMask = (1 << 3);
      const cloudsBitMask = (1 << 5);
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
      return image.updateMask(mask).select(['SR_B.*', 'ST_B.*']).copyProperties(image, ["system:time_start"]);
    }

    // Function to calculate NDVI for Landsat collections (handles different band names)
    function addNdvi(image) {
      let nir, red;
      if (image.get('system:index').match('LC08')) { // Landsat 8
        nir = 'SR_B5';
        red = 'SR_B4';
      } else if (image.get('system:index').match('LE07|LT05')) { // Landsat 7/5
        nir = 'SR_B4';
        red = 'SR_B3';
      } else {
        return image.addBands(ee.Image(-999).rename('NDVI')); // Return a dummy band for unsupported sensors
      }
      return image.normalizedDifference([nir, red]).rename('NDVI').copyProperties(image, ["system:time_start"]);
    }

    // --- Target Period (February 2021) ---
    let l8_2021_collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
      .filterBounds(analysisRegion)
      .filterDate(startTarget, endTarget)
      .map(maskL8Cloud)
      .map(addNdvi);

    const count_l8_2021 = await l8_2021_collection.size().getInfo();
    if (count_l8_2021 === 0) {
      console.log(`2021 Images (L8): 0`);
      console.log("No images found for February 2021. Trying Landsat 9 (if available for 2021)...");
      // Fallback to Landsat 9 if Landsat 8 has no images
      l8_2021_collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_SR')
        .filterBounds(analysisRegion)
        .filterDate(startTarget, endTarget)
        .map(maskL8Cloud) // LC09 has same band naming and QA_PIXEL as LC08
        .map(addNdvi);
      const count_l9_2021 = await l8_2021_collection.size().getInfo();
      if (count_l9_2021 === 0) {
        console.log(`2021 Images (L9): 0`);
        console.log("C1: Empty Collection (No images found for February 2021).");
        console.log("C1");
        return;
      }
      console.log(`2021 Images (L9): ${count_l9_2021}`);
    } else {
      console.log(`2021 Images (L8): ${count_l8_2021}`);
    }

    const mean_ndvi_2021_image = l8_2021_collection.select('NDVI').mean();
    const result_2021 = await mean_ndvi_2021_image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: analysisRegion,
      scale: 30, // Landsat resolution
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    if (result_2021 === null) {
      // Check pixel count if result is null
      const validPixels_2021 = await l8_2021_collection.select('NDVI').mean().reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: analysisRegion,
        scale: 30,
        maxPixels: 1e9
      }).get('NDVI').getInfo();

      if (validPixels_2021 === 0) {
        console.log("No valid pixels for February 2021 after cloud masking.");
        console.log("C2");
        return;
      } else {
        console.log("Calculation failure for 2021 NDVI (Result is null but pixels exist).");
        console.log("C3");
        return;
      }
    }

    // --- Baseline Period (February 2010-2020) ---
    let baselineNdviMeans = [];
    let totalBaselineImages = 0;

    for (let year = startBaselineYear; year <= endBaselineYear; year++) {
      const startBaseline = ee.Date.fromYMD(year, month, 1);
      const endBaseline = ee.Date.fromYMD(year, month, 1).advance(1, 'month');

      let currentCollection;
      if (year >= 2013) { // Landsat 8 started in 2013
        currentCollection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR');
      } else if (year >= 1999) { // Landsat 7 for 1999-2012
        currentCollection = ee.ImageCollection('LANDSAT/LE07/C02/T1_SR');
      } else { // Landsat 5 for earlier years, if needed (not for this question's range)
        currentCollection = ee.ImageCollection('LANDSAT/LT05/C02/T1_SR');
      }

      let yearCollection = currentCollection
        .filterBounds(analysisRegion)
        .filterDate(startBaseline, endBaseline)
        .map(maskL8Cloud) // Masking logic is general enough for C02/T1_SR across sensors
        .map(addNdvi);

      const count_year = await yearCollection.size().getInfo();
      totalBaselineImages += count_year;

      if (count_year > 0) {
        const mean_ndvi_year_image = yearCollection.select('NDVI').mean();
        const result_year = await mean_ndvi_year_image.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: analysisRegion,
          scale: 30,
          maxPixels: 1e9
        }).get('NDVI').getInfo();

        if (result_year !== null && !isNaN(result_year)) {
          baselineNdviMeans.push(result_year);
          console.log(`Feb ${year} Images: ${count_year} (Val: ${result_year.toFixed(3)})`);
        } else {
          // Check pixel count if result is null/NaN
          const validPixels_year = await yearCollection.select('NDVI').mean().reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: analysisRegion,
            scale: 30,
            maxPixels: 1e9
          }).get('NDVI').getInfo();
          console.log(`Feb ${year} Images: ${count_year} (Val: Null/NaN, Pixels: ${validPixels_year})`);
        }
      } else {
        console.log(`Feb ${year} Images: ${count_year}`);
      }
    }

    if (totalBaselineImages === 0) {
      console.log("C1: Empty Collection (No images found for baseline period 2010-2020).");
      console.log("C1");
      return;
    }
    if (baselineNdviMeans.length === 0) {
      console.log("No valid pixels for baseline period after cloud masking.");
      console.log("C2");
      return;
    }

    const baseline_average_ndvi = baselineNdviMeans.reduce((a, b) => a + b, 0) / baselineNdviMeans.length;

    // 5. Validation & Final Answer
    console.log(`2021 February NDVI: ${result_2021.toFixed(3)}`);
    console.log(`2010-2020 February Average NDVI: ${baseline_average_ndvi.toFixed(3)}`);

    if (result_2021 === null || isNaN(result_2021) || baseline_average_ndvi === null || isNaN(baseline_average_ndvi)) {
      console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
      console.log("C3");
    } else if (result_2021 > baseline_average_ndvi) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (e) {
    console.error("D: An error occurred:", e);
    console.log("D");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
